import { z } from "zod";

/**
 * Server environment, validated once at startup (see instrumentation.ts).
 * In production a missing or weak value stops the server from booting instead of failing at checkout.
 */
// DEMO_MODE=1: a showcase deployment without payment keys — checkout explains that online payment is
// not enabled yet, everything else works. Never set it on the real store.
const demo = process.env.DEMO_MODE === "1";
const rzp = <T extends z.ZodTypeAny>(s: T) => (demo ? s.optional().or(z.literal("")) : s);

const schema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  DATABASE_URL: z.string().startsWith("postgresql://", "DATABASE_URL must be a postgresql:// URL"),
  NEXT_PUBLIC_SITE_URL: z.url(),
  RAZORPAY_KEY_ID: rzp(z.string().regex(/^rzp_(test|live)_[A-Za-z0-9]+$/, "RAZORPAY_KEY_ID looks wrong")),
  RAZORPAY_KEY_SECRET: rzp(z.string().min(10)),
  RAZORPAY_WEBHOOK_SECRET: rzp(z.string().min(8, "Set RAZORPAY_WEBHOOK_SECRET (Dashboard → Webhooks)")),
  NEXT_PUBLIC_RAZORPAY_KEY_ID: rzp(z.string().regex(/^rzp_(test|live)_/)),
  CRON_SECRET: z.string().min(24, "CRON_SECRET must be at least 24 random characters"),
  SMTP_HOST: z.string().optional(),
  SMTP_PORT: z.coerce.number().optional(),
  SMTP_USER: z.string().optional(),
  SMTP_PASS: z.string().optional(),
  MAIL_FROM: z.string().optional(),
  STORE_NOTIFY_EMAIL: z.email().optional(),
  UPLOAD_DIR: z.string().optional(),
});

export function validateEnv() {
  const isProd = process.env.NODE_ENV === "production" && process.env.NEXT_PHASE !== "phase-production-build";
  const parsed = schema.safeParse(process.env);
  if (parsed.success) {
    const e = parsed.data;
    const problems: string[] = [];
    const local = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(e.NEXT_PUBLIC_SITE_URL);
    if (isProd && !e.NEXT_PUBLIC_SITE_URL.startsWith("https://") && !local) problems.push("NEXT_PUBLIC_SITE_URL must use https:// in production");
    if (demo) console.warn("[env] DEMO_MODE is on — online payments are disabled. Do not use for the real store.");
    if (isProd && e.RAZORPAY_KEY_ID?.startsWith("rzp_test_")) console.warn("[env] Razorpay is in TEST mode — switch to rzp_live_ keys before taking real orders.");
    if ((e.RAZORPAY_KEY_ID || e.NEXT_PUBLIC_RAZORPAY_KEY_ID) && e.RAZORPAY_KEY_ID !== e.NEXT_PUBLIC_RAZORPAY_KEY_ID) problems.push("NEXT_PUBLIC_RAZORPAY_KEY_ID must equal RAZORPAY_KEY_ID");
    if (!e.SMTP_HOST) console.warn("[env] SMTP is not configured — order/lead emails and password resets are disabled.");
    if (problems.length && isProd) throw new Error(`Invalid environment:\n - ${problems.join("\n - ")}`);
    return;
  }
  const msg = parsed.error.issues.map((i) => ` - ${i.path.join(".")}: ${i.message}`).join("\n");
  if (isProd) throw new Error(`Invalid environment:\n${msg}`);
  console.warn(`[env] Development environment is incomplete (fine for local work):\n${msg}`);
}

export const smtpConfigured = () => Boolean(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS);
