import "server-only";
import nodemailer, { type Transporter } from "nodemailer";
import { db } from "./db";
import { smtpConfigured } from "./env";
import { formatINR } from "./money";
import { SITE } from "./site";

let transport: Transporter | null = null;

function mailer() {
  transport ??= nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT ?? 465),
    secure: Number(process.env.SMTP_PORT ?? 465) === 465,
    auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
  });
  return transport;
}

const esc = (s: unknown) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

function layout(title: string, body: string) {
  return `<!doctype html><html><body style="margin:0;background:#faf8f5;font-family:Arial,Helvetica,sans-serif;color:#16181d">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#faf8f5;padding:24px 0"><tr><td align="center">
  <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fff;border:1px solid #e7e2da;border-radius:12px;overflow:hidden">
    <tr><td style="background:#16181d;padding:18px 24px;color:#fff;font-size:20px;font-weight:bold;letter-spacing:1px">SUN METALS STORE</td></tr>
    <tr><td style="padding:24px"><h1 style="font-size:20px;margin:0 0 12px">${esc(title)}</h1>${body}</td></tr>
    <tr><td style="background:#faf8f5;padding:16px 24px;font-size:12px;color:#6b7280">
      ${esc(SITE.address.line1)}, ${esc(SITE.address.city)}, ${esc(SITE.address.state)} – ${esc(SITE.address.pincode)} · GSTIN ${esc(SITE.gstin)}<br>
      ${esc(SITE.phone)} · <a href="mailto:${esc(SITE.email)}" style="color:#8b1e1e">${esc(SITE.email)}</a>
    </td></tr>
  </table></td></tr></table></body></html>`;
}

const button = (href: string, label: string) =>
  `<p style="margin:20px 0"><a href="${esc(href)}" style="background:#b8862b;color:#fff;padding:12px 20px;border-radius:999px;text-decoration:none;font-weight:bold">${esc(label)}</a></p>`;

/** Never throws: email problems are logged, not surfaced to shoppers. */
export async function sendMail(to: string, subject: string, html: string, replyTo?: string) {
  if (!smtpConfigured()) {
    console.info(`[email] SMTP not configured; skipped "${subject}" to ${to}`);
    return;
  }
  try {
    await mailer().sendMail({ from: process.env.MAIL_FROM ?? `${SITE.name} <${process.env.SMTP_USER}>`, to, subject, html, replyTo });
  } catch (err) {
    console.error(JSON.stringify({ level: "error", message: "email send failed", subject, error: (err as Error).message }));
  }
}

const ownerEmail = () => process.env.STORE_NOTIFY_EMAIL ?? SITE.email;

export async function sendOrderConfirmation(orderId: string) {
  const o = await db.order.findUnique({ where: { id: orderId }, include: { items: true } });
  if (!o) return;
  const a = o.shippingAddress as Record<string, string>;
  const rows = o.items
    .map(
      (i) => `<tr><td style="padding:8px 0;border-bottom:1px solid #eee">${esc(i.name)}${i.engravingText ? `<br><span style="color:#b8862b;font-size:12px">Engraving: “${esc(i.engravingText)}”</span>` : ""}</td>
      <td style="padding:8px 0;border-bottom:1px solid #eee;text-align:center">${i.quantity}</td>
      <td style="padding:8px 0;border-bottom:1px solid #eee;text-align:right">${formatINR(i.unitPrice * i.quantity)}</td></tr>`,
    )
    .join("");
  const table = `<table width="100%" style="border-collapse:collapse;font-size:14px">${rows}
    <tr><td colspan="2" style="padding-top:10px">Delivery</td><td style="padding-top:10px;text-align:right">${o.shippingFee ? formatINR(o.shippingFee) : "FREE"}</td></tr>
    ${o.discount ? `<tr><td colspan="2">Discount</td><td style="text-align:right">−${formatINR(o.discount)}</td></tr>` : ""}
    <tr><td colspan="2" style="font-weight:bold;padding-top:6px">Total paid</td><td style="font-weight:bold;text-align:right;padding-top:6px">${formatINR(o.total)}</td></tr></table>`;
  const addr = `<p style="font-size:14px;color:#3b4049">Delivering to: ${esc(a.name)}, ${esc(a.line1)}${a.line2 ? `, ${esc(a.line2)}` : ""}, ${esc(a.city)}, ${esc(a.state)} – ${esc(a.pincode)}</p>`;

  await sendMail(
    o.email,
    `Order confirmed #${o.orderNumber} — ${SITE.name}`,
    layout(`Thank you, ${a.name}! Your order is confirmed.`, `<p style="font-size:14px">Order <b>#${esc(o.orderNumber)}</b>${o.invoiceNumber ? ` · Invoice ${esc(o.invoiceNumber)}` : ""}</p>${table}${addr}${button(`${SITE.url}/order/${o.orderNumber}`, "Track your order")}<p style="font-size:13px;color:#6b7280">Questions? Reply to this email or WhatsApp us at ${esc(SITE.phone)}.</p>`),
    ownerEmail(),
  );
  await sendMail(
    ownerEmail(),
    `🛒 New order #${o.orderNumber} — ${formatINR(o.total)} via ${o.paymentMethod ?? "online"}`,
    layout(`New order #${o.orderNumber}`, `<p style="font-size:14px">${esc(a.name)} · ${esc(o.phone)} · ${esc(a.city)}</p>${table}${button(`${SITE.url}/admin/orders/${o.id}`, "Open in admin")}`),
  );
}

export async function sendShippingUpdate(orderId: string) {
  const o = await db.order.findUnique({ where: { id: orderId } });
  if (!o) return;
  const a = o.shippingAddress as Record<string, string>;
  const title = o.status === "SHIPPED" ? "Your order is on its way 🚚" : o.status === "DELIVERED" ? "Your order has been delivered" : `Order update: ${o.status.toLowerCase()}`;
  await sendMail(
    o.email,
    `${title} — #${o.orderNumber}`,
    layout(title, `<p style="font-size:14px">Hi ${esc(a.name)}, order <b>#${esc(o.orderNumber)}</b> is now <b>${esc(o.status.toLowerCase())}</b>.</p>${o.trackingNumber ? `<p style="font-size:14px">Courier: ${esc(o.courier)} · Tracking no. <b>${esc(o.trackingNumber)}</b></p>` : ""}${button(`${SITE.url}/order/${o.orderNumber}`, "View order")}`),
    ownerEmail(),
  );
}

export async function sendCancellation(orderId: string, refundNote: string) {
  const o = await db.order.findUnique({ where: { id: orderId } });
  if (!o) return;
  await sendMail(
    o.email,
    `Order #${o.orderNumber} cancelled`,
    layout("Your order has been cancelled", `<p style="font-size:14px">Order <b>#${esc(o.orderNumber)}</b> was cancelled. ${esc(refundNote)}. Refunds reach your account in 5–7 working days.</p>`),
    ownerEmail(),
  );
  await sendMail(ownerEmail(), `Order #${o.orderNumber} cancelled by customer`, layout("Customer cancelled an order", `<p>#${esc(o.orderNumber)} · ${formatINR(o.total)} · ${esc(refundNote)}</p>`));
}

export async function sendLeadAlert(lead: { type: string; name: string; company?: string | null; phone: string; email?: string | null; city?: string | null; message?: string | null; details: Record<string, string> }) {
  const label = lead.type === "B2B_QUOTE" ? "B2B quote request" : lead.type === "ENGRAVING" ? "Engraving request" : "Contact enquiry";
  const details = Object.entries(lead.details)
    .map(([k, v]) => `<tr><td style="padding:4px 12px 4px 0;color:#6b7280;text-transform:capitalize">${esc(k)}</td><td>${esc(v)}</td></tr>`)
    .join("");
  await sendMail(
    ownerEmail(),
    `📩 New ${label} from ${lead.name}${lead.company ? ` (${lead.company})` : ""}`,
    layout(`New ${label}`, `<p style="font-size:14px"><b>${esc(lead.name)}</b>${lead.company ? ` · ${esc(lead.company)}` : ""}<br>📞 ${esc(lead.phone)}${lead.email ? ` · ${esc(lead.email)}` : ""}${lead.city ? ` · ${esc(lead.city)}` : ""}</p>${lead.message ? `<p style="font-size:14px;white-space:pre-line;background:#faf8f5;padding:12px;border-radius:8px">${esc(lead.message)}</p>` : ""}<table style="font-size:13px">${details}</table>${button(`${SITE.url}/admin/leads`, "Open leads inbox")}`),
    lead.email || undefined,
  );
}

export async function sendPasswordReset(to: string, name: string, link: string) {
  await sendMail(
    to,
    `Reset your ${SITE.name} password`,
    layout("Reset your password", `<p style="font-size:14px">Hi ${esc(name)}, we received a request to reset your password. This link is valid for 30 minutes and can be used once.</p>${button(link, "Choose a new password")}<p style="font-size:12px;color:#6b7280">If you didn’t ask for this, you can ignore this email — your password won’t change.</p>`),
  );
}
